function removeCourse(courseId){ensureCourses();if(state.courses.length<2)return showError('Plansza musi mieć co najmniej jeden tor.');const index=state.courses.findIndex(course=>course.id===courseId);if(index<0)return;const wasActive=state.courses[index].id===state.activeCourseId;state.courses.splice(index,1);if(wasActive){const next=state.courses[Math.max(0,index-1)];state.activeCourseId=next.id;state.route=next.route;state.routeBends=next.routeBends;state.path=next.color}sync();draw();markDirty();toast('Usunięto tor')}
