function routeNodes(route=state.route,automatic=activeCourse()?.automatic){const byId=new Map(state.obstacles.map(o=>[o.id,o]));const visits=Array.isArray(route)?route.map((visit,index)=>({visit,index,key:typeof visit==='string'?visit:visit?.obstacleId})).filter(item=>byId.has(item.key)):[];return visits.length?visits.map(({visit,index,key})=>{const obstacle=byId.get(key);return{...obstacle,n:Number.isInteger(visit?.n)?visit.n:obstacle.n,_reverse:visit?.reverse===true,_visitIndex:index,_visitKey:`${key}@${index}`}}):automatic?[...state.obstacles].sort((a,b)=>a.n-b.n):[]}function obstacleTraversal(nodes,index,beforeOverride,afterOverride){const o=nodes[index];if(!o)return null;const scale=state.unit==='ft'?.3048:1,angle=(Number(o.rotation)||0)*Math.PI/180,count=Number(o.poleCount)===6?6:12,shape=o.type==='tunnel'?tunnelPath(Number(o.length)||4.5,o.bend,32):o.type==='weave'?[{x:-((count-1)*.3+.3),y:0},...Array.from({length:count},(_,i)=>({x:(i-(count-1)/2)*.6,y:i%2?.27:-.27})),{x:(count-1)*.3+.3,y:0}]:[{x:0,y:-obstacleFootprint(o).depth/2},{x:0,y:obstacleFootprint(o).depth/2}],points=shape.map(p=>({x:o.x+(p.x*Math.cos(angle)-p.y*Math.sin(angle))/(state.length*scale),y:o.y+(p.x*Math.sin(angle)+p.y*Math.cos(angle))/(state.width*scale)}));const meters=(p,q)=>Math.hypot((p.x-q.x)*state.length*scale,(p.y-q.y)*state.width*scale),before=beforeOverride||nodes[index-1],after=afterOverride||nodes[index+1];let enterFromStart;if(before)enterFromStart=meters(points[0],before)<meters(points.at(-1),before);else if(after)enterFromStart=meters(points.at(-1),after)<meters(points[0],after);else enterFromStart=true;if(!enterFromStart)points.reverse();if(o._reverse)points.reverse();return{entry:points[0],exit:points.at(-1),points};}
