 const startTangent=ta?{x:(ta.exit.x-ta.points.at(-2).x)*w,y:(ta.exit.y-ta.points.at(-2).y)*h}:null,endTangent=tb?{x:(tb.points[1].x-tb.entry.x)*w,y:(tb.points[1].y-tb.entry.y)*h}:null;
 const norm=v=>{const d=Math.hypot(v.x,v.y)||1;return{x:v.x/d,y:v.y/d}},st=startTangent&&norm(startTangent),et=endTangent&&norm(endTangent);
