 const c2=et?{x:p3.x-et.x*align+nx*offset,y:p3.y-et.y*align+ny*offset}:{x:p3.x-(pn.x-p0.x)*.18+nx*offset-Math.cos(rb)*align,y:p3.y-(pn.y-p0.y)*.18+ny*offset-Math.sin(rb)*align};
