function pointerMove(e){const p=coords(e);$('#coord').textContent=`${(p.x*state.length).toFixed(1)} × ${(p.y*state.width).toFixed(1)} ${state.unit}`;if(dragCurve){const {w,h}=dim(),scale=Math.min(w,h),dx=(p.x-dragCurve.start.x)*w,dy=(p.y-dragCurve.start.y)*h;state.routeBends[dragCurve.key]=Math.max(-.28,Math.min(.28,dragCurve.bend+(dx*dragCurve.nx+dy*dragCurve.ny)/scale));dragCurve.moved=true;draw();return}if(dragRotation){const o=state.obstacles.find(item=>item.id===dragRotation.id);if(!o)return;const {w,h}=dim(),angle=Math.atan2((p.y-o.y)*h,(p.x-o.x)*w);let delta=angle-dragRotation.start;while(delta>Math.PI)delta-=Math.PI*2;while(delta<-Math.PI)delta+=Math.PI*2;const raw=dragRotation.initial+delta*180/Math.PI;o.rotation=((raw+180)%360+360)%360-180;dragRotation.moved=true;$('#obstacleRotation').value=Math.round(o.rotation);draw();return}if(!drag){canvas.style.cursor=rotationHandleHit(p)?'grab':'';return}const o=state.obstacles.find(o=>o.id===drag.id);if(!o)return;if(!drag.moved){saveHistory();drag.moved=true}o.x=Math.max(.06,Math.min(.94,p.x-drag.dx));o.y=Math.max(.08,Math.min(.92,p.y-drag.dy));draw();updateRouteList()}
