function addObstacle(type){if(!names[type])return showError('Nieznany typ przeszkody.');if(state.obstacles.length>=99)return showError('Możesz dodać maksymalnie 99 przeszkód.');const used=new Set(state.obstacles.map(o=>Number(o.n)));let n=1;while(used.has(n)&&n<=99)n++;if(n>99)return showError('Brak wolnego numeru przeszkody.');const explicit=routeNodes().map(o=>o._visitIndex!=null?state.route[o._visitIndex]:{obstacleId:o.id,n:o.n});saveHistory();const o={id:id(),type,x:.5,y:.5,n,label:'',rotation:0};if(type==='tunnel'){o.length=4.5;o.bend=0}if(type==='weave')o.poleCount=12;if(type==='aFrame')o.height=1.7;if(type==='tire')o.height=.8;if(type==='dogWalk')o.height=1.2;state.obstacles.push(o);if(state.route?.length||!activeCourse().automatic){state.route=explicit.concat({obstacleId:o.id,n:o.n});activeCourse().automatic=false}state.selected=o.id;state.tool='select';saveActiveCourse();sync();draw();markDirty();toast(`${names[type]} dodana do aktywnego toru`)}function deleteSelected(){if(!state.selected)return;saveHistory();const deleted=state.selected;state.obstacles=state.obstacles.filter(o=>o.id!==deleted);state.courses.forEach(course=>course.route=course.route.filter(visit=>(typeof visit==='string'?visit:visit?.obstacleId)!==deleted));state.route=activeCourse().route;const ordered=[...state.obstacles].sort((a,b)=>a.n-b.n),numbers=[...new Set(ordered.map(o=>Number(o.n)))],remap=new Map(numbers.map((n,i)=>[n,i+1]));ordered.forEach(o=>o.n=remap.get(Number(o.n)));state.selected=null;updateSelection();updateRouteList();draw();markDirty();toast('Usunięto przeszkodę i zaktualizowano numery')}function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.remove('error');t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function autosave(){try{localStorage.setItem('agility-map-project',JSON.stringify({...state,selected:null,tool:'select'}));$('#saveState').textContent='Zapisano lokalnie';$('#saveState').parentElement.querySelector('i').style.background='var(--lime)'}catch(error){$('#saveState').textContent='Błąd zapisu';showError(`Nie udało się zapisać projektu w przeglądarce: ${error.message}`)}}
