function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJSON(){try{download(new Blob([JSON.stringify({...state,selected:null,tool:'select'},null,2)],{type:'application/json'}),`${slug(state.title)}.json`);toast('Projekt zapisany do pliku')}catch(error){showError(`Eksport projektu nie powiódł się: ${error.message}`)}}
