async function setView(view){if(view==='2d'){state.view='2d';sync();$('#hint').innerHTML=state.tool==='route'?'<b>Trasa automatyczna</b> · Przeciągnij uchwyt na linii, aby zmienić łuk':'<b>Wskazówka</b> · Kliknij numer, aby go zmienić; przeciągnij uchwyt nad przeszkodą, aby obrócić';draw();markDirty();return}state.view='3d';sync();$('#hint').innerHTML='<b>Widok 3D</b> · Alt + przeciągnij przeszkodę, aby ją obrócić; Shift + przeciągnij lub prawy przycisk przesuwa kamerę';try{if(!scene3d){if(!scene3dLoading)scene3dLoading=(async()=>{const {createScene3D}=await import('./scene-3d.js?v=agility-independent-courses-20261011');return createScene3D({canvas:$('#scene3dCanvas'),getState:()=>state,onSelect:id=>{state.selected=id;updateSelection();draw()},onEditNumber:(id,visitIndex)=>{const obstacle=state.obstacles.find(item=>item.id===id);if(obstacle)openNumberEditor(obstacle,visitIndex)},onRotate:(id,rotation)=>{const obstacle=state.obstacles.find(item=>item.id===id);if(obstacle){obstacle.rotation=rotation;document.getElementById("obstacleRotation").value=rotation;draw()}},onMove:(id,x,y)=>{const o=state.obstacles.find(item=>item.id===id);if(o){o.x=x;o.y=y;$('#coord').textContent=`${(x*state.length).toFixed(1)} × ${(y*state.width).toFixed(1)} ${state.unit}`;draw();updateRouteList()}},onBend:(key,value)=>{state.routeBends[key]=value;draw()},onDone:markDirty,onError:message=>{if(state.view==='3d'){state.view='2d';sync();draw()}showError(message)}})})();scene3d=await scene3dLoading}draw();markDirty()}catch(error){scene3d=null;scene3dLoading=null;state.view='2d';sync();draw();showError(`Nie udało się uruchomić widoku 3D. Sprawdź obsługę WebGL i połączenie z internetem. (${error.message})`)}}
